mapper.select:
SELECT MIN(device_sn) FROM ast_device_shipment WHERE tenant_id=#{query.tenantId} AND deleted=0 AND source_system='DPPMS' AND CAST(device_sn AS BINARY)>CAST(#{query.afterSn} AS BINARY)
AND device_sn IN #{sn}
GROUP BY CAST(device_sn AS BINARY) ORDER BY CAST(device_sn AS BINARY) LIMIT 500

SELECT ranked.* FROM (
  SELECT s.*,ROW_NUMBER() OVER(PARTITION BY CAST(device_sn AS BINARY) ORDER BY shipment_time DESC,id DESC) AS latest_rank
  FROM ast_device_shipment s WHERE tenant_id=#{query.tenantId} AND deleted=0


      AND device_sn IN #{sn}

    AND 1=0

) ranked WHERE latest_rank=1
